      "content": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"0.6\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f59e0b\"/><stop offset=\"1\" stop-color=\"#b53a0b\"/></linearGradient><clipPath id=\"c\"><rect width=\"64\" height=\"64\" rx=\"18\"/></clipPath></defs><g clip-path=\"url(#c)\"><rect width=\"64\" height=\"64\" fill=\"url(#g)\"/><circle cx=\"32\" cy=\"66\" r=\"22\" fill=\"#fff7ec\"/></g></svg>\n"
