      "content": "<!doctype html>\n<html lang=\"en-GB\" data-palette=\"fresh\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Booking request sent | Brightwell Cleaning</title>\n  <meta name=\"robots\" content=\"noindex\" />\n  <link rel=\"icon\" href=\"assets/favicon.svg\" type=\"image/svg+xml\" />\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Gabarito:wght@500;700;800&family=Onest:wght@400;500;600&display=swap\" />\n  <link rel=\"stylesheet\" href=\"styles.css\" />\n  <script>\n    document.documentElement.classList.add('js');\n    (function () { try { var t = localStorage.getItem('spotless-theme'); if (t === 'light' || t === 'dark') document.documentElement.setAttribute('data-theme', t); } catch (e) {} })();\n  </script>\n</head>\n<body>\n  <a class=\"skip-link\" href=\"#main\">Skip to content</a>\n  <header class=\"site-header\">\n    <div class=\"container header-inner\">\n      <a class=\"brand\" href=\"index.html\" aria-label=\"Brightwell Cleaning, home\">\n        <svg class=\"brand-mark\" viewBox=\"0 0 40 40\" aria-hidden=\"true\"><path d=\"M20 3c1.2 8.6 4.4 11.8 13 13-8.6 1.2-11.8 4.4-13 13-1.2-8.6-4.4-11.8-13-13 8.6-1.2 11.8-4.4 13-13Z\"/><path class=\"mini\" d=\"M32 25c.5 3.3 1.7 4.5 5 5-3.3.5-4.5 1.7-5 5-.5-3.3-1.7-4.5-5-5 3.3-.5 4.5-1.7 5-5Z\"/></svg>\n        <span class=\"brand-name\">Brightwell<span>Cleaning Co.</span></span>\n      </a>\n      <div class=\"header-actions\">\n        <button class=\"icon-btn theme-toggle\" type=\"button\" aria-label=\"Switch to dark theme\" data-theme-toggle>\n          <svg class=\"icon-sun\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4.2\"/><path d=\"M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M5.3 18.7l1.4-1.4M17.3 6.7l1.4-1.4\"/></svg>\n          <svg class=\"icon-moon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5Z\"/></svg>\n        </button>\n        <a class=\"btn btn-small\" href=\"index.html#quote\">Get a quote</a>\n      </div>\n    </div>\n  </header>\n  <main id=\"main\" class=\"page\">\n    <div class=\"container\">\n      <p class=\"eyebrow\">Request received</p>\n      <h1>Thanks! We&rsquo;ll call you within one working day.</h1>\n      <p class=\"lead\">We&rsquo;ll confirm your price, check access and any must-dos, and book your first clean.</p>\n      <p>In a hurry? Call us on <a href=\"tel:+442079460321\">020 7946 0321</a>, Monday to Saturday, 8am to 6pm.</p>\n      <p><a class=\"btn\" href=\"index.html\">Back to the home page</a></p>\n    </div>\n  </main>\n  <footer class=\"site-footer\">\n    <div class=\"container footer-grid\">\n      <p class=\"muted small\">Brightwell Cleaning Co. &middot; <a href=\"tel:+442079460321\">020 7946 0321</a> &middot; <a href=\"mailto:hello@example.com\">hello@example.com</a></p>\n      <nav class=\"footer-links\" aria-label=\"Footer\"><a href=\"index.html\">Home</a><a href=\"privacy.html\">Privacy</a></nav>\n      <p class=\"small muted footer-legal\">&copy; <span data-year>2026</span> Brightwell Cleaning Ltd</p>\n    </div>\n  </footer>\n  <script src=\"main.js\" defer></script>\n</body>\n</html>\n"
